steps.script:
# Config is one thing; what is actually ON THE BOARD is the claim. Count the
# player-1 units that came from the Custodes list, and prove no Ork unit did.
var custodes = 0
var orks = 0
for uid in GameState.state.get("units", {}).keys():
	var u = GameState.state["units"][uid]
	if int(u.get("owner", 0)) != 1:
		continue
	var kw = u.get("meta", {}).get("keywords", [])
	if "ADEPTUS CUSTODES" in kw or "CUSTODES" in kw or str(uid).begins_with("U_CUSTODIAN") or str(uid).begins_with("U_BLADE_CHAMPION"):
		custodes += 1
	if "ORKS" in kw:
		orks += 1
print("SCENARIO plan_editor_army on board: custodes=%d orks=%d" % [custodes, orks])
return "custodes>0=%s orks=%d" % [str(custodes > 0), orks]

# The faction the game itself reports for seat 1.
var f = GameState.state.get("factions", {}).get("1", {})
print("SCENARIO plan_editor_army faction: %s / %s" % [str(f.get("name", "")), str(f.get("detachment", ""))])
return str(f.get("name", ""))
